// Supongamos que los items de entrada son pasados a la variable 'users'  
const users = $input.all(); // Recupera todos los usuarios  
const filterCriteria = $('Revisar prioridad').first().json['Dirección de correo electrónico'] || $('Revisar prioridad').first().json['Dirección de correo electrónico']; // Cambia esto por el correo o nombre de usuario que desees filtrar  

const filteredIds = users.filter(user => {  
    // Comprueba si el correo o el nombre de usuario coincide con el criterio  
    return user.json.profile.email === filterCriteria || user.json.name === filterCriteria;  
}).map(user => user.json.id); // Recupera solo los IDs  

return [{ json: { filteredIds } }]; // Devuelve los IDs filtrados

// Clonar el objeto de entrada para no modificarlo directamente
const output = { ...$json };

// Obtener la fecha desde el JSON de entrada
const fechaOriginal = output["Fecha limite"];

if (!fechaOriginal) {
  output["Fecha limite"] = "Fecha no disponible";
  return [output];
}

try {
  // Separar la fecha por "/"
  const partes = fechaOriginal.split("/");

  // Asegurar que tenemos día, mes y año
  if (partes.length !== 3) {
    output["Fecha limite"] = "Formato inválido";
    return [output];
  }

  // Convertir a formato YYYY-MM-DD
  const dia = partes[0].padStart(2, "0");  // Asegurar que el día tenga 2 dígitos
  const mes = partes[1].padStart(2, "0");  // Asegurar que el mes tenga 2 dígitos
  const anio = partes[2];

  output["Fecha limite"] = `${anio}-${mes}-${dia}`;
  return [output];

} catch (error) {
  output["Fecha limite"] = "Error en conversión";
  return [output];
}

